def generate_Interleaved(pp_size, chunk_size, num_microbatches,input_str):
    stage_alignment = []
    for i in range(pp_size):
        stages_in_ranks = []
        for j in range(chunk_size):
            stages_in_ranks.append(i+j*pp_size)
        stage_alignment.append(stages_in_ranks)
    print(stage_alignment)
    unified_scheduler = order_result_mutichunk(input_str,stage_alignment,chunk_size, num_microbatches)
    comm_graph = comm_graph_muti_chunk(unified_scheduler,stage_alignment)
    return stage_alignment, unified_scheduler, comm_graph
import json

def generate_Interleaved_4pp_20chunk_16mb():
    pp_size = 4
    chunk_size = 20
    num_microbatches = 16
    stage_alignment = []
    for i in range(pp_size):
        stages_in_ranks = []
        for j in range(chunk_size):
            stages_in_ranks.append(i+j*pp_size)
        stage_alignment.append(stages_in_ranks)

    input_str = read_input_str_in_result_file()
    unified_scheduler = order_result_mutichunk(input_str,stage_alignment,chunk_size, num_microbatches)
    comm_graph = comm_graph_muti_chunk(unified_scheduler,stage_alignment)
    return stage_alignment, unified_scheduler, comm_graph

import os
def generate(layer_num, chunk_size):
    stage_alignment = read_placement_from_file()
    pp_size = len(stage_alignment)
    schedule = read_input_str_in_result_file()
    num_microbatches = get_num_microbatches(schedule=schedule)
    unified_scheduler = order_result_mutichunk(schedule,stage_alignment,chunk_size, num_microbatches)
    comm_graph = comm_graph_muti_chunk(unified_scheduler,stage_alignment)
    return stage_alignment, unified_scheduler, comm_graph

def get_num_microbatches(schedule:str):
    max_mid = -1
    for line in schedule.split('\n'):
        if line.startswith("b_"):
            mid = eval(line.split('_')[1])
            max_mid = max(mid, max_mid)
    return max_mid + 1

def read_input_str_in_result_file(filepath="InternEvo/result.txt"):
    input_str = open(file=filepath, mode='r').read()
    return input_str

def read_placement_from_file(filepath="InternEvo/placement.txt"):
    stage_alignment = eval(open(file=filepath, mode='r').read())
    return stage_alignment

